CREATE DATABASE IF NOT EXISTS ops_platform CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE ops_platform;
CREATE TABLE IF NOT EXISTS system_announcement (id BIGINT NOT NULL AUTO_INCREMENT,title VARCHAR(128) NOT NULL,content TEXT NOT NULL,status VARCHAR(16) NOT NULL,create_by BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_announcement_status_time(status,create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS operation_audit (id BIGINT NOT NULL AUTO_INCREMENT,service_name VARCHAR(64) NOT NULL,biz_type VARCHAR(64) NOT NULL,biz_id VARCHAR(64),operation VARCHAR(64) NOT NULL,user_id BIGINT,trace_id VARCHAR(64),request_id VARCHAR(64),detail_json JSON,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_audit_biz_time(biz_type,biz_id,create_time),KEY idx_audit_trace(trace_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS platform_config (id BIGINT NOT NULL AUTO_INCREMENT,config_key VARCHAR(128) NOT NULL,config_value TEXT,description VARCHAR(512),update_by BIGINT,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_platform_config_key(config_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mq_consumed_event (id BIGINT NOT NULL AUTO_INCREMENT,consumer_name VARCHAR(128) NOT NULL,event_id CHAR(36) NOT NULL,consume_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_consumer_event(consumer_name,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
